import { localizedPrice } from "@/lib/localized-price";
import { resolveFreeTemplate } from "@/lib/template-policy";
import { Suspense } from "react";
import { WorkspaceSkeleton } from "@/components/workspace-skeleton";
import Form from "next/form";
import Link from "next/link";
import { requireUser } from "@/lib/session";
import { readShortlist } from "@/lib/shortlist";
import { db } from "@/lib/db";
import { readQuotaSnapshot } from "@/lib/quota-usage";
import { Compose } from "@/components/compose";
import { Input } from "@/components/ui/input";
import { SearchButton } from "@/components/search-button";
import { Pagination } from "@/components/pagination";
import { pageNumber } from "@/lib/params";
export const metadata = { title: "Compose" };
async function ComposePageContent({
  searchParams,
}: {
  searchParams: Promise<{ q?: string; page?: string }>;
}) {
  const user = await requireUser();
  const freeTemplateId = await resolveFreeTemplate(db, user.id);
  const params = await searchParams;
  const q = (params.q ?? "").slice(0, 160);
  const page = pageNumber(params.page);
  const [templates, shortlist, quota, attachment, premiumPrice] =
    await Promise.all([
      db.template.findMany({
        where: { userId: user.id, archivedAt: null },
        select: { id: true, name: true, subject: true, body: true },
        orderBy: { name: "asc" },
      }),
      readShortlist(user.id, q, page),
      readQuotaSnapshot(user.id),
      user.currentAttachmentId
        ? db.attachment.findFirst({
            where: { id: user.currentAttachmentId, userId: user.id },
            select: { fileName: true },
          })
        : null,
      localizedPrice(Promise.resolve({})),
    ]);
  const { contacts, total } = shortlist;
  const recipients = contacts.map((c) => ({
    ...c,
    lastSent: c.lastSent?.toISOString() ?? null,
  }));
  // Snapshot the persisted account wait for this authenticated server response.
  // eslint-disable-next-line react-hooks/purity
  const observedAt = Date.now();
  return (
    <>
      <Compose
        recipientSearchQuery={q}
        recipientSearch={
          total > 5 || q.length > 0 ? (
            <Form
              action="/compose"
              scroll={false}
              className="compose-search mb-4 grid grid-cols-[minmax(0,1fr)_auto] gap-2"
            >
              <label
                htmlFor="compose-search"
                className="col-span-2 text-xs font-medium"
              >
                Search recipients
              </label>
              <Input
                id="compose-search"
                key={q}
                name="q"
                defaultValue={q}
                autoComplete="off"
                placeholder="Name, email, or company…"
              />
              <SearchButton />
              {q.length > 0 && (
                <Link
                  href="/compose"
                  scroll={false}
                  className="col-span-2 inline-flex min-h-11 items-center justify-self-start text-xs text-link"
                >
                  Clear search
                </Link>
              )}
            </Form>
          ) : null
        }
        premiumPrice={premiumPrice}
        nextSendAt={user.nextSendAt?.toISOString() ?? null}
        observedAt={observedAt}
        templates={templates.map((template) => ({
          ...template,
          eligible: template.id === freeTemplateId,
        }))}
        contacts={recipients}
        quota={quota}
        roles={user.preferredRoles}
        resume={attachment?.fileName ?? null}
        connected={user.gmailAuthorized && !!user.encryptedRefreshToken}
      />
      <Pagination path="/compose" page={page} total={total} query={{ q }} />
    </>
  );
}

export default function ComposePage(
  props: Parameters<typeof ComposePageContent>[0],
) {
  return (
    <div className="compose-page">
      <div className="compose-hero mb-6">
        <div>
          <h1>Compose</h1>
          <p>Personalized outreach, one recipient at a time.</p>
        </div>
      </div>
      <Suspense fallback={<WorkspaceSkeleton page="compose" heading={false} />}>
        <ComposePageContent {...props} />
      </Suspense>
    </div>
  );
}
